package br.com.provas.service;
import br.com.provas.model.entity.QuestaoSorteio;import br.com.provas.model.request.ComposicaoProvaRequest;import br.com.provas.exceptions.DefaultErrorException;import org.junit.jupiter.api.Test;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;
class QuestionDrawServiceTest {
 private QuestaoSorteio q(long id,long subject,String weight){return new QuestaoSorteio(id,id,"discursiva",new BigDecimal(weight),"Questão",Map.of(),null,subject);}
 @Test void drawsVariableCountsWithDecimalWeightsAndEverySubject(){var pool=List.of(q(1,1,"1.25"),q(2,1,"1.25"),q(3,1,"1.25"),q(4,2,"2.5"),q(5,2,"2.5"));var plan=List.of(new ComposicaoProvaRequest(1L,new BigDecimal("1.25"),2),new ComposicaoProvaRequest(2L,new BigDecimal("2.5"),1));for(int i=0;i<100;i++){var result=QuestionDrawService.draw(pool,plan);assertEquals(3,result.size());assertEquals(3,result.stream().map(QuestaoSorteio::id).distinct().count());assertEquals(0,result.stream().map(QuestaoSorteio::peso).reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(new BigDecimal("5")));assertEquals(2,result.stream().filter(q->q.assuntoId()==1L).count());}}
 @Test void changedStockDoesNotSilentlyChangeDistribution(){assertThrows(DefaultErrorException.class,()->QuestionDrawService.draw(List.of(q(1,1,"1.25")),List.of(new ComposicaoProvaRequest(1L,new BigDecimal("1.25"),3))));}
 @Test void refusesFewerThanThreeQuestions(){assertThrows(DefaultErrorException.class,()->QuestionDrawService.draw(List.of(q(1,1,"1"),q(2,1,"1")),List.of(new ComposicaoProvaRequest(1L,BigDecimal.ONE,2))));}
}
